76: func (w *RollFileWriter) Write(v []byte) (int, error) {
77: 	if w.currFile == nil || w.openTime+10 < currUnixTime {
78: 		fullPath := filepath.Join(w.logpath, fmt.Sprintf("%s.log", w.name))
79: 		reOpenFile(fullPath, &w.currFile, &w.openTime)
80: 	}
81: 	if w.currFile == nil {
82: 		return 0, errors.New("w.currFile was nil")
83: 	}
84: 	n, _ := w.currFile.Write(v)
85: 	w.currSize += int64(n)
86: 	if w.size > 0 && w.num >= 1 && w.currSize >= w.size {
87: 		// file_num is total retained files (live + numbered backups), matching
88: 		// Cubelet config.toml. Shift only through `.log.(num-1)` so we do
89: 		// not keep an extra `.log.num` after dropping the racy async delete.
90: 		live := filepath.Join(w.logpath, fmt.Sprintf("%s.log", w.name))
91: 		if w.num == 1 {
92: 			if w.currFile != nil {
93: 				_ = w.currFile.Close()
94: 				w.currFile = nil
95: 			}
96: 			if err := os.Truncate(live, 0); err != nil && !os.IsNotExist(err) {
97: 				fmt.Fprintf(os.Stderr, "cubelog: failed to truncate %s: %v\n", live, err)
98: 				return n, nil
99: 			}
100: 			w.currSize = 0
101: 			reOpenFile(live, &w.currFile, &w.openTime)
102: 			return n, nil
103: 		}
104: 		var liveRenameErr error
105: 		for i := w.num - 1; i >= 1; i-- {
106: 			var n1, n2 string
107: 			if i > 1 {
108: 				n1 = strconv.Itoa(i - 1)
109: 			}
110: 			n2 = strconv.Itoa(i)
111: 			p1 := filepath.Join(w.logpath, fmt.Sprintf("%s.log.%s", w.name, n1))
112: 			p2 := filepath.Join(w.logpath, fmt.Sprintf("%s.log.%s", w.name, n2))
113: 			if n1 == "" {
114: 				p1 = live
115: 			}
116: 			err := os.Rename(p1, p2)
117: 			if i == 1 {
118: 				liveRenameErr = err
119: 			}
120: 			if err != nil && !os.IsNotExist(err) {
121: 				fmt.Fprintf(os.Stderr, "cubelog: failed to rotate %s to %s: %v\n", p1, p2, err)
122: 			}
123: 		}
124: 		if liveRenameErr != nil && !os.IsNotExist(liveRenameErr) {
125: 			// Keep currSize so a failed live rename cannot restart the
126: 			// unbounded-append path this PR is closing. ENOENT means the
127: 			// live path is gone (e.g. operator deleted it); fall through
128: 			// and reopen so later writes are not lost on the unlinked inode.
129: 			// This guard only fires when `.log.1` itself cannot be replaced
130: 			// (typical num==2). For num>=3 a blocker at `.log.1` is shifted
131: 			// to `.log.2` first, so the live rename usually succeeds.
132: 			return n, nil
133: 		}
134: 		w.currSize = 0
135: 		reOpenFile(live, &w.currFile, &w.openTime)
136: 	}
137: 
138: 	return n, nil
139: }

